import React, { useState, useContext } from 'react';
import { Container, TextField, Box, Typography, IconButton, InputAdornment, FormControlLabel, Checkbox, Link, Button, Alert } from '@mui/material';
import { Visibility, VisibilityOff } from '@mui/icons-material';
import { AuthContext } from '../context/AuthContext';
import { useNavigate, Link as RouterLink } from 'react-router-dom';

const LoginCard = () => {
  const { login } = useContext(AuthContext);
  const navigate = useNavigate();

  const [showPassword, setShowPassword] = useState(false);
  const [form, setForm] = useState({ email: '', password: '' });
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const togglePassword = () => {
    setShowPassword(!showPassword);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    try {
      const res = await login(form.email, form.password);
      if (res.success) {
        navigate('/');
      } else {
        setError(res.error);
      }
    } catch (err) {
      setError('An unexpected error occurred. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <Container maxWidth="xs">
      <Box sx={{ mt: 10, p: 4, bgcolor: '#f0f8ff', borderRadius: 3, boxShadow: 3 }}>
        <Typography variant="h5" align="center" mb={3}>
          Welcome to the <strong>Movie Explorer</strong>
        </Typography>

        {error && (
          <Alert severity="error" sx={{ mb: 2, borderRadius: 2 }}>
            {error}
          </Alert>
        )}

        <form onSubmit={handleSubmit}>
          <TextField
            label="Email"
            name="email"
            type="email"
            variant="standard"
            required
            fullWidth
            margin="normal"
            value={form.email}
            onChange={handleChange}
          />
          <TextField
            label="Password"
            name="password"
            variant="standard"
            required
            fullWidth
            margin="normal"
            value={form.password}
            onChange={handleChange}
            type={showPassword ? 'text' : 'password'}
            InputProps={{
              endAdornment: (
                <InputAdornment position="end">
                  <IconButton onClick={togglePassword} edge="end">
                    {showPassword ? <VisibilityOff /> : <Visibility />}
                  </IconButton>
                </InputAdornment>
              ),
            }}
          />

          <FormControlLabel
            control={<Checkbox color="primary" />}
            label="Remember me"
            sx={{ mt: 1, display: 'flex', justifyContent: 'flex-start' }}
          />

          <Button
            type="submit"
            fullWidth
            variant="contained"
            disabled={loading}
            sx={{ mt: 3, bgcolor: '#023e8a', '&:hover': { bgcolor: '#0077b6' }, borderRadius: '25px', padding: '10px' }}
          >
            {loading ? 'Logging In...' : 'Log In'}
          </Button>

          <Box sx={{ display: 'flex', justifyContent: 'space-between', mt: 3 }}>
            <Link href="#" variant="body2" sx={{ textDecoration: 'none' }}>
              Forgot password?
            </Link>
            <Link component={RouterLink} to="/Register" variant="body2" sx={{ textDecoration: 'none', fontWeight: 'bold' }}>
              Sign Up
            </Link>
          </Box>
        </form>
      </Box>
    </Container>
  );
};

export default LoginCard;
